    APX_A_KEY_DESC_C='Guías centrales',
    APX_A_KEY_USE_C='cruz amarilla translúcida en los ejes',
    APX_A_KEY_DESC_D='Descargar PNG',
    APX_A_KEY_USE_D='canvas actual como imagen PNG',
    APX_A_KEY_DESC_I='Chip de info',
    APX_A_KEY_USE_I='conteo de bloques y desglose de packs',
    APX_A_KEY_DESC_M='Alterna 2D / 3D',
